def analyze_corner(grid, corner_name, rows=5, cols=4):
    """Extract corner region and count active cells"""
    if corner_name == 'TL':
        region = grid[0:rows, 0:cols]
    elif corner_name == 'TR':
        region = grid[0:rows, -cols:]
    elif corner_name == 'BL':
        region = grid[-rows:, 0:cols]
    elif corner_name == 'BR':
        region = grid[-rows:, -cols:]
    return region, np.sum(region > 0)

